import { Component, inject, NgZone, OnInit, signal } from '@angular/core';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { AuthenticationService } from '../../userservices/authentication.service';
import { first } from 'rxjs/operators';
import { AlertService } from '../../../utils/alert/alert.service';
import { AlertComponent } from '../../../utils/alert/alert/alert.component';

@Component({
  selector: 'app-signin',
  imports: [RouterModule, AlertComponent, ReactiveFormsModule],
  templateUrl: './signin.component.html',
  styleUrls: ['./signin.component.css']
})
export class SigninComponent implements OnInit {

  private formBuilder: FormBuilder = inject(FormBuilder);
  private route: ActivatedRoute = inject(ActivatedRoute);
  private router: Router = inject(Router);
  private authenticationService: AuthenticationService = inject(AuthenticationService);
  private alertService: AlertService = inject(AlertService);
  private zone: NgZone = inject(NgZone);

  loading = signal<boolean>(false);
  submitted = signal<boolean>(false);

  signinForm: FormGroup;
  returnUrl: string | null = null;

  constructor() {
    if (this.authenticationService.currentUserValue) {
      this.router.navigate(['/user/dashboard']);
    }
    this.signinForm = this.formBuilder.group({
      username: ['', Validators.required],
      password: ['', Validators.required]
    });
  }

  ngOnInit() {
    this.returnUrl = this.route.snapshot.queryParams['returnUrl'] || '/user/dashboard';
  }

  get f() { return this.signinForm?.controls; };

  onSubmit() {
    this.submitted.set(true);
    if (this.signinForm?.invalid) {
      return;
    }
    this.loading.set(true);
    this.authenticationService.signIn(this.f?.['username'].value, this.f?.['password'].value)
      .pipe(first())
      .subscribe({
        next: (data) => {
          if (data['success']) {
            this.alertService.success(data['ops']);
            this.zone.run(() => {
              this.router.navigate([this.returnUrl]);
            })
          } else {
            this.alertService.error(data['ops']);
            this.loading.set(false);
          }
        },
        error: (error) => {
          this.alertService.error(error);
          this.loading.set(false);
        },
        complete: () => { this.loading.set(false) }
      }
      );
  }
}
